// src/components/Header.js
import React, { useState } from "react";
import "./Header.css";

function Header() {
  const [dropdownOpen, setDropdownOpen] = useState(false);

  // Try to read currentUser from localStorage
  let user = { firstName: "User", lastName: "", role: "", profilePic: "" };
  try {
    const cu = JSON.parse(localStorage.getItem("currentUser") || "null");
    if (cu) {
      // prefer displayName or email fallback
      const namePart = (cu.email && cu.email.split("@")[0]) || cu.name || "User";
      user.firstName = namePart;
      user.lastName = "";
      user.role = cu.role ? cu.role.charAt(0).toUpperCase() + cu.role.slice(1) : "";
      user.profilePic = cu.profilePic || "";
    }
  } catch (e) {
    // keep default
  }

  const getInitials = (first, last) => {
    if (!first) return "U";
    return first[0].toUpperCase();
  };

  return (
    <div className="header">
      {/* Search bar */}
      <div className="search-container">
        <input type="text" placeholder="Search candidates or clients..." />
      </div>

      {/* Profile */}
      <div 
        className="profile-container" 
        onMouseEnter={() => setDropdownOpen(true)}
        onMouseLeave={() => setDropdownOpen(false)}
      >
        <div className="profile-info">
          {user.profilePic ? (
            <img src={user.profilePic} alt="Profile" className="profile-img" />
          ) : (
            // plain pink circle
            <div className="profile-placeholder profile-placeholder-pink">
              {getInitials(user.firstName, user.lastName)}
            </div>
          )}
          <div className="profile-text">
            <span className="profile-name">User</span>
            <span className="profile-role">{user.role}</span>
          </div>
        </div>

        {dropdownOpen && (
          <ul className="profile-dropdown">
            <li>My Account</li>
            <li>Profile</li>
            <li>Billing</li>
            <li>Logout</li>
          </ul>
        )}
      </div>
    </div>
  );
}

export default Header;
